// ==========================================================================
// Board::CanZombieSpawnOnLevel(ZombieType,int)
// @0015215C  90 bytes
// ==========================================================================
bool Board::CanZombieSpawnOnLevel(ZombieType theZombieType, int theLevel)
{
  ZombieDefinition *aDefinition = GetZombieDefinition(theZombieType);
  if ( theZombieType == ZOMBIE_YETI )
    return gLawnApp->CanSpawnYetis();
  if ( aDefinition->mStartingLevel > theLevel )
    return false;
  if ( aDefinition->mZombieCost == 0 )
    return false;

  // The original table stores a type tag before each row's 50 level permissions.
  int aLevelIndex = theLevel - 1;
  if ( aLevelIndex > 0 )
  {
    if ( aLevelIndex >= 49 )
      aLevelIndex = 49;
  }
  else
    aLevelIndex = 0;
  return gZombieAllowedLevels[theZombieType][aLevelIndex];
}

// ==========================================================================
// Board::PutInMissingZombies(int,ZombiePicker *)
// @001521C4  76 bytes
// ==========================================================================
int Board::PutInMissingZombies(int theWaveIndex, ZombiePicker *thePicker)
{
  // Walk every zombie type and add the first one the level allows that this
  // wave still has none of. The yeti is never added automatically.
  for ( int i = 0; i < NUM_ZOMBIE_TYPES; ++i )
  {
    if ( i == ZOMBIE_YETI )
      continue;
    if ( thePicker->mZombieTypeCount[i] <= 0 && CanZombieSpawnOnLevel((ZombieType)i, mLevel) )
      return PutZombieInWave((ZombieType)i, theWaveIndex, thePicker);
  }
  return 0;
}

// ==========================================================================
// Board::IsZombieWaveDistributionOk()
// @00152210  160 bytes
// ==========================================================================
int Board::IsZombieWaveDistributionOk()
{
  // Adventure levels must use every zombie type they allow at least once.
  if ( !mApp->IsAdventureMode() )
    return 1;

  int aZombieTypeCount[NUM_ZOMBIE_TYPES] = { 0 };
  for ( int aWave = 0; aWave < mNumWaves; ++aWave )
    for ( int aSlot = 0; aSlot < MAX_ZOMBIES_IN_WAVE; ++aSlot )
    {
      ZombieType aType = mZombiesInWave[aWave][aSlot];
      if ( aType == ZOMBIE_INVALID )
        break;
      ++aZombieTypeCount[aType];
    }

  for ( int i = 0; i < NUM_ZOMBIE_TYPES; ++i )
  {
    if ( i == ZOMBIE_YETI )
      continue;
    if ( CanZombieSpawnOnLevel((ZombieType)i, mLevel) && aZombieTypeCount[i] == 0 )
      return 0;
  }
  return 1;
}

// ==========================================================================
// Board::InitZombieWavesForLevel(int)
// @001522B0  90 bytes
// ==========================================================================
int Board::InitZombieWavesForLevel(int theLevel)
{
  // These three modes build their waves in Challenge rather than from the table.
  if ( mApp->IsWhackAZombieLevel()
    || (mApp->IsWallnutBowlingLevel() && !mApp->IsFirstTimeAdventureMode())
    || mApp->mGameMode == GAMEMODE_CHALLENGE_HEAVY_WEAPON )
  {
    mChallenge->InitZombieWaves();
    return 0;
  }

  int result = 0;
  for ( int i = 0; i < NUM_ZOMBIE_TYPES; ++i )
    result = mZombieAllowed[i] = CanZombieSpawnOnLevel((ZombieType)i, theLevel);
  return result;
}

// ==========================================================================
// Board::GetIntroducedZombieType()
// @0015230C  94 bytes
// ==========================================================================
int Board::GetIntroducedZombieType()
{
  // The zombie whose first level is this one -- the one the level introduces.
  if ( !mApp->IsAdventureMode() || mLevel == 1 )
    return -1;

  for ( int i = 0; i < NUM_ZOMBIE_TYPES; ++i )
  {
    if ( i == ZOMBIE_YETI && !mApp->CanSpawnYetis() )
      continue;
    // GetZombieDefinition's +0x0C field is the zombie's first level.
    if ( GetZombieDefinition(i)->mStartingLevel == mLevel )
      return i;
  }
  return -1;
}

// ==========================================================================
// Board::PickGraveRisingZombieTypeMP(int)
// @0015236C  254 bytes
// ==========================================================================
int Board::PickGraveRisingZombieTypeMP(int theLevel)
{
  // Each pair is { zombie type, cost }. The 0x114-byte frame is 69 words;
  // the picker only reads the pairs this function fills.
  TodWeightedArray aWeights[69];
  int aCount = 0;
  GameMode aMode = mApp->mGameMode;
  if ( aMode == GAMEMODE_MP_VS_DEBUG )
  {
    if ( theLevel > 3 )
    {
      aWeights[0].mItem = 23;
      aWeights[0].mWeight = GetZombieDefinition(23)->mZombieCost;
      aWeights[1].mItem = 22;
      aWeights[1].mWeight = GetZombieDefinition(22)->mZombieCost;
      aWeights[2].mItem = 12;
      aWeights[2].mWeight = GetZombieDefinition(12)->mZombieCost;
      aCount = 3;
    }
    else
    {
      switch ( theLevel )
      {
        case 3:
          aWeights[0].mItem = 6;
          aWeights[0].mWeight = GetZombieDefinition(6)->mZombieCost;
          aWeights[1].mItem = 15;
          aWeights[1].mWeight = GetZombieDefinition(15)->mZombieCost;
          aCount = 2;
          break;
        case 2:
          aWeights[0].mItem = 3;
          aWeights[0].mWeight = GetZombieDefinition(3)->mZombieCost;
          aWeights[1].mItem = 7;
          aWeights[1].mWeight = GetZombieDefinition(7)->mZombieCost;
          aCount = 2;
          break;
        case 1:
          aWeights[0].mItem = 5;
          aWeights[0].mWeight = GetZombieDefinition(5)->mZombieCost;
          aWeights[1].mItem = 2;
          aWeights[1].mWeight = GetZombieDefinition(2)->mZombieCost;
          aCount = 2;
          break;
        default:
          aWeights[0].mItem = 0;
          aWeights[0].mWeight = GetZombieDefinition(0)->mZombieCost;
          aCount = 1;
          break;
      }
    }
    return TodPickFromWeightedArray(aWeights, aCount);
  }
  if ( aMode != GAMEMODE_MP_VS )
    return TodPickFromWeightedArray(aWeights, 0);
  switch ( theLevel )
  {
    case 0:
      return 0;
    case 1:
      return 6;
    case 2:
      return 3;
    case 3:
      return 7;
    case 4:
      return 23;
    default:
      return TodPickFromWeightedArray(aWeights, 0);
  }
}

// ==========================================================================
