// ==========================================================================
// Board::CanAddBobSled()
// @0015247C  36 bytes
// ==========================================================================
int Board::CanAddBobSled()
{
  // A bob-sled needs a row with ice that has not reached the house yet.
  for ( int aRow = 0; aRow < MAX_GRID_SIZE_Y; ++aRow )
    if ( mIceTimer[aRow] > 0 && mIceMinX[aRow] < 700 )
      return 1;
  return 0;
}

