// ==========================================================================
// Board::dumpAllowedZombiesInLevel()
// @00162FC0
// The stream is an ostringstream. A space is written only when the buffer
// already has text, so numbers are separated and the result has no trailing space.
// ==========================================================================
Sexy::String Board::dumpAllowedZombiesInLevel()
{
  std::ostringstream aStream;
  for (int i = 0; i != 100; ++i)
  {
    if (mZombieAllowed[i] == 0)
      continue;
    if (aStream.tellp() != std::streampos(0))
      aStream << ' ';
    aStream << i;
  }
  return aStream.str();
}

// ==========================================================================
// Board::dumpZombiesInWave(int)
// @0016335C
// ostringstream. ", " separates types only when the buffer already has text.
// The walk stops at ZOMBIE_INVALID or the end of the wave. Points are the sum
// of each type's mZombieValue, then the literal " \t\t\tpoints: ".
// ==========================================================================
Sexy::String Board::dumpZombiesInWave(int aWave)
{
  std::ostringstream aStream;
  int aPoints = 0;
  ZombieType *aSlot = &mZombiesInWave[aWave][0];
  ZombieType *aEnd = aSlot + MAX_ZOMBIES_IN_WAVE;
  while (aSlot != aEnd)
  {
    ZombieType aType = *aSlot++;
    if (aType == ZOMBIE_INVALID)
      break;
    if (aStream.tellp() != std::streampos(0))
      aStream << ", ";
    ZombieDefinition *aDefinition = GetZombieDefinition(aType);
    aStream << static_cast<int>(aType);
    aPoints += aDefinition->mZombieValue;
  }
  aStream << " \t\t\tpoints: ";
  aStream << aPoints;
  return aStream.str();
}

