// ==========================================================================
// Board::ProcessDeleteQueue()
// @00164730  768 bytes
// ==========================================================================
// ---------------------------------------------------------------------------
// The six arrays below are walked by hand. A `DataArray<T>` slot is
//     struct DataArrayItem { T mItem; unsigned int mID; };
// so the id sits immediately after the item, the low half of it is the slot
// index and the high half is the key -- a slot is in use while that key half is
// non-zero. Freeing an item destroys it and pushes its slot index onto the
// array's free list, which is what DataArray<T>::DataArrayFree does.
// ---------------------------------------------------------------------------

static void ErasePlantFromTree(std::set<Plant *> &theTree, Plant *thePlant)
{
    theTree.erase(thePlant);
}

// The shared body of the five arrays whose items have no side table to leave.
template <class T, class Slot>
static void FreeDeadBoardItems(DataArray<T, Slot> &theArray)
{
    T *anItem = nullptr;
    while (theArray.IterateNext(anItem))
    {
        if (!anItem->mDead)
            continue;
        theArray.DataArrayFree(anItem);
        anItem = nullptr;
    }
}

int Board::ProcessDeleteQueue()
{
    // A pumpkin shell, a flower pot and a tangle kelp are also indexed by one of
    // the board's trees, so they have to leave that tree before their slot is
    // reused.
    PlantSlot *aPlantSlot = mPlants.mBlock;
    PlantSlot *anEnd = aPlantSlot + mPlants.mMaxUsedCount;
    for ( ; aPlantSlot < anEnd; ++aPlantSlot )
    {
        if ( (aPlantSlot->mID & 0xFFFF0000) == 0 || !aPlantSlot->mItem.mDead )
            continue;

        switch ( aPlantSlot->mItem.mSeedType )
        {
        case SEED_TANGLEKELP:
            ErasePlantFromTree(mTangleKelpTree, &aPlantSlot->mItem);
            break;
        case SEED_PUMPKINSHELL:
            ErasePlantFromTree(mPumpkinTree, &aPlantSlot->mItem);
            break;
        case SEED_FLOWERPOT:
            ErasePlantFromTree(mFlowerPotTree, &aPlantSlot->mItem);
            break;
        default:
            break;
        }

        mPlants.DataArrayFree(&aPlantSlot->mItem);
    }

    FreeDeadBoardItems<Zombie>(mZombies);
    FreeDeadBoardItems<Projectile>(mProjectiles);
    FreeDeadBoardItems<Coin>(mCoins);
    FreeDeadBoardItems<LawnMower>(mLawnMowers);
    FreeDeadBoardItems<GridItem>(mGridItems);

    // The binary leaves the grid-item array's used count in r0 and returns it;
    // no caller reads the value.
    return mGridItems.mMaxUsedCount;
}

// ==========================================================================
// Board::RemovedFromManager(Sexy::WidgetManager *)
